import type { ProfileRecords } from '../../storage/profiles/ProfileRecords';
import { isRemoteProfileProvider } from '../../types/design-profile';
import {
  isSourceSyncAllowed,
  type SourceSyncCheck,
} from '../../types/source-sync';
import { reconnectRequiredMessage } from './ProfileImports';
import { remoteSourceInterval } from './SourceSyncSchedule';

const IN_PROGRESS_JOB_STATES = new Set(['pending', 'paused']);

type ProfileSource = ReturnType<ProfileRecords['sources']>[number];

const sourceJobs = (records: ProfileRecords, sourceId: string) =>
  records.jobs().filter((job) => job.sourceId === sourceId);

export const lastReferenceJob = (records: ProfileRecords, sourceId: string) =>
  sourceJobs(records, sourceId).slice(-1)[0];

const automaticSyncJob = (records: ProfileRecords, source: ProfileSource) => {
  if (
    !records.profile().isEnabled ||
    !isRemoteProfileProvider(source.provider) ||
    !isSourceSyncAllowed({ syncMode: source.syncMode, trigger: 'automatic' })
  )
    return null;
  const jobs = sourceJobs(records, source.id);
  const last = jobs[jobs.length - 1];
  if (
    !last ||
    jobs.some((job) => IN_PROGRESS_JOB_STATES.has(job.state)) ||
    (last.state === 'failed' &&
      last.error === reconnectRequiredMessage(source.provider))
  )
    return null;
  return last;
};

export const isAutomaticReferenceSyncAllowed = (
  records: ProfileRecords,
  sourceId: string,
): boolean => {
  const source = records.sources().find((item) => item.id === sourceId);
  return Boolean(source && automaticSyncJob(records, source));
};

export const referenceSyncChecks = (
  records: ProfileRecords,
): SourceSyncCheck[] =>
  records.sources().flatMap((source) => {
    const last = automaticSyncJob(records, source);
    return last
      ? [
          {
            family: 'references' as const,
            sourceId: source.id,
            dueAt: Date.parse(last.updatedAt) + remoteSourceInterval(source.id),
          },
        ]
      : [];
  });
